      "content": "{\n  \"name\": \"dsh-openbitfun\",\n  \"version\": \"0.1.0\",\n  \"description\": \"DeepSeek Harness plugin bundle exposing the OpenBitFun Agent SDK Host as dsh tools\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"cordis.patch.yml\",\n    \"README.md\"\n  ],\n  \"license\": \"MIT\",\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  }\n}\n"
